try:
    from scipy.optimize import least_squares
except Exception as e:
    print('noscipy',e)
y=dv_dt
def model(p,t,x,v):
    F0,w,ph,c,q,k,b,d=p
    return F0*np.cos(w*t+ph) - c*v**q - k*x - b*x**3 - d
best=None
rng=np.random.default_rng(0)
for trial in range(300):
    p0=[rng.uniform(0,6),rng.uniform(0.2,4),rng.uniform(-3,3),rng.uniform(0,3),rng.uniform(0.5,2),rng.uniform(-3,8),rng.uniform(-2,2),rng.uniform(-2,2)]
    try:
        r=least_squares(lambda p: model(p,t,x,v)-y, p0, max_nfev=2000)
    except Exception:
        continue
    e=np.mean(r.fun**2)/np.var(y)
    if best is None or e<best[0]: best=(e,r.x)
print(best)
